import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class LifecycleJUnit5Test {
    @BeforeAll
    static void setupAll() {
        System.out.println("Setup ALL TESTS in the class");
    }
    @BeforeEach
    void setup() {
        System.out.println("Setup EACH TEST in the class");
    }
    @Test
    void testOne() {
        System.out.println("TEST 1");
    }
    @Test
    void testTwo() {
        System.out.println("TEST 2");
    }
    @AfterEach
    void teardown() {
        System.out.println("Teardown EACH TEST in the class");
    }
    @AfterAll
    static void teardownAll() {
        System.out.println("Teardown ALL TESTS in the class");
    }
}

class StandardAssertionsTest {
    @Test
    void standardAssertions() {
        assertEquals(2, 2);
        assertTrue(true, "The optional assertion message is now the last parameter");
        assertFalse(false, () -> "Really " + "expensive " + "message" + ".");
    }
}

class GroupedAssertionsTest {
    @Test
    void groupedAssertions() {
        Address address = new Address("John", "Smith");
        assertAll("address", () -> assertEquals("John", address.getFirstName()), () -> assertEquals("User", address.getLastName()));
    }
}

class ExceptionTest {
    @Test
    void exceptionTesting() {
        Throwable exception = assertThrows(IllegalArgumentException.class, () -> { throw new IllegalArgumentException("a message");});
        assertEquals("a message", exception.getMessage());
    }
}

class TimeoutExceededTest {
    @Test
    void timeoutNotExceeded() {
        assertTimeout(ofMinutes(2), () -> {
            Thread.sleep(100); });
    }
    @Test
    void timeoutExceeded() {
        assertTimeout(ofMillis(10), () -> {
            Thread.sleep(100); });
    }
}

class TimeoutWithResultOrMethodTest {
    @Test
    void timeoutNotExceededWithResult() {
        String actualResult = assertTimeout(ofMinutes(1), () -> { return "hi there"; });
        assertEquals("hi there", actualResult);
    }
    @Test
    void timeoutNotExceededWithMethod() {
        String actualGreeting = assertTimeout(ofMinutes(1), TimeoutWithResultOrMethodTest::greeting);
        assertEquals("hello world!", actualGreeting);
    }
    private static String greeting() { return "hello world!"; }
}

class TimeoutWithPreemptiveTerminationTest {
    @Test void timeoutExceededWithPreemptiveTermination() {
        assertTimeoutPreemptively(ofMillis(10), () -> { Thread.sleep(100); });
    }
}

class CollectionTest {
    // Warning: this test will raise an exception
    @TestFactory
    List<String> dynamicTestsWithInvalidReturnType() {
        return Arrays.asList("Hello"); }
    @TestFactory
    Collection<DynamicTest> dynamicTestsFromCollection() {
        return Arrays.asList( dynamicTest("1st dynamic test", () -> assertTrue(true)), dynamicTest("2nd dynamic test", () -> assertEquals(4, 2 * 2))); }
    @TestFactory
    Iterable<DynamicTest> dynamicTestsFromIterable() {
        return Arrays.asList( dynamicTest("3rd dynamic test", () -> assertTrue(true)), dynamicTest("4th dynamic test", () -> assertEquals(4, 2 * 2))); }
    @TestFactory
    Iterator<DynamicTest> dynamicTestsFromIterator() {
        return Arrays.asList( dynamicTest("5th dynamic test", () -> assertTrue(true)), dynamicTest("6th dynamic test", () -> assertEquals(4, 2 * 2))).iterator(); }
}

import static org.junit.jupiter.api.DynamicTest.dynamicTest;
import java.util.stream.Stream;
import org.junit.jupiter.api.DynamicTest;
import org.junit.jupiter.api.TestFactory;

class DynamicExampleTest {
    @TestFactory
    Stream<DynamicTest> dynamicTestsFromStream() {
        Stream<String> inputStream = Stream.of("A", "B", "C");
        return inputStream.map( input -> dynamicTest("Display name for input " + input, () -> { System.out.println("Testing " + input); })); }
}

class StreamExampleTest {
    @TestFactory
    Stream<DynamicTest> streamTest() {
        // Input data
        Integer array[] = { 1, 2, 3 };
        Iterator<Integer> inputGenerator = Arrays.asList(array).iterator();

        // Display names
        Function<Integer, String> displayNameGenerator = ( input) -> "Data input:" + input;

        // Test executor
        ThrowingConsumer<Integer> testExecutor = (input) -> { System.out.println(input); assertTrue(input % 2 == 0); };

        // Returns a stream of dynamic tests
        return stream(inputGenerator, displayNameGenerator, testExecutor); }
}

